package com.bananalab.lite;
import java.util.*;
/** Typed expression compiler: parses every token, no arbitrary Java text enters output. */
final class Formula{
 static final class Node{final String op;final Node[] children;final boolean bool;final int number;
 Node(String o,boolean b,int n,Node...c){op=o;bool=b;number=n;children=c;}
 String java(){if(op.equals("x"))return "a[i]";if(op.equals("n"))return Integer.toString(number);String a=children[0].java();if(op.equals("neg")||op.equals("abs"))return "FormulaMath."+op+"("+a+")";if(op.equals("!"))return "(!"+a+")";String b=children[1].java();if(op.equals("?:"))return "("+a+"?"+b+":"+children[2].java()+")";if(op.matches("add|sub|mul|div|mod"))return "FormulaMath."+op+"("+a+","+b+")";return "("+a+op+b+")";}
 long eval(int x){if(op.equals("x"))return x;if(op.equals("n"))return number;long a=children[0].eval(x);if(op.equals("!"))return a==0?1:0;if(op.equals("neg"))return bound(-a);if(op.equals("abs"))return bound(Math.abs(a));if(op.equals("?:"))return children[a!=0?1:2].eval(x);if(op.equals("&&")&&a==0)return 0;if(op.equals("||")&&a!=0)return 1;long b=children[1].eval(x);if(op.equals("add"))return bound(a+b);if(op.equals("sub"))return bound(a-b);if(op.equals("mul"))return bound(a*b);if(op.equals("div")||op.equals("mod")){if(b==0)throw new IllegalArgumentException("Division por cero");return bound(op.equals("div")?a/b:a%b);}if(op.equals("&&"))return b!=0?1:0;if(op.equals("||"))return b!=0?1:0;return (op.equals(">")?a>b:op.equals("<")?a<b:op.equals(">=")?a>=b:op.equals("<=")?a<=b:op.equals("==")?a==b:a!=b)?1:0;}
 }
 static long bound(long x){if(x < -1000000 || x > 1000000)throw new IllegalArgumentException("Intermedio fuera de rango");return x;}
 final List<String> tokens=new ArrayList<>();int at=0,nodes=0,depth=0;
 Formula(String s){if(s.length()>240)throw new IllegalArgumentException("Formula demasiado larga");java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\s*(>=|<=|==|!=|&&|\\|\\||[0-9]+|[a-z]+|[()+*/%?:!<>-])").matcher(s);int end=0;while(m.find()){if(m.start()!=end)throw new IllegalArgumentException("Simbolo desconocido en la formula");tokens.add(m.group(1));end=m.end();}if(!s.substring(end).trim().isEmpty()||tokens.size()>96)throw new IllegalArgumentException("Formula incompleta o demasiado grande");}
 Node node(String op,boolean bool,int n,Node... c){if(++nodes>64)throw new IllegalArgumentException("Formula demasiado compleja");return new Node(op,bool,n,c);}
 boolean take(String s){if(at<tokens.size()&&tokens.get(at).equals(s)){at++;return true;}return false;}
 void expect(String s){if(!take(s))throw new IllegalArgumentException("Falta "+s+" en la formula");}
 static void type(Node n,boolean bool){if(n.bool!=bool)throw new IllegalArgumentException("Tipos incompatibles en la formula");}
 Node expression(){if(++depth>24)throw new IllegalArgumentException("Formula muy anidada");Node n=binary(0);if(take("?")){type(n,true);Node yes=expression();expect(":");Node no=expression();if(yes.bool!=no.bool)throw new IllegalArgumentException("Ramas incompatibles");n=node("?:",yes.bool,0,n,yes,no);}depth--;return n;}
 static final String[][] OPS={{"||"},{"&&"},{"==","!="},{">","<",">=","<="},{"+","-"},{"*","/","%"}};
 Node binary(int level){if(level==OPS.length)return unary();Node n=binary(level+1);while(at<tokens.size()&&Arrays.asList(OPS[level]).contains(tokens.get(at))){String op=tokens.get(at++);Node right=binary(level+1);boolean logical=level<2;type(n,logical);type(right,logical);String name=op.equals("+")?"add":op.equals("-")?"sub":op.equals("*")?"mul":op.equals("/")?"div":op.equals("%")?"mod":op;n=node(name,level<4,0,n,right);}return n;}
 Node unary(){if(++depth>24)throw new IllegalArgumentException("Formula muy anidada");Node n;if(take("-")){n=unary();type(n,false);n=node("neg",false,0,n);}else if(take("!")){n=unary();type(n,true);n=node("!",true,0,n);}else if(take("abs")){expect("(");n=expression();expect(")");type(n,false);n=node("abs",false,0,n);}else if(take("(")){n=expression();expect(")");}else if(take("x"))n=node("x",false,0);else{if(at>=tokens.size()||!tokens.get(at).matches("[0-9]{1,4}"))throw new IllegalArgumentException("Esperaba numero o x");int value=Integer.parseInt(tokens.get(at++));if(value>1000)throw new IllegalArgumentException("Constante fuera de rango");n=node("n",false,value);}depth--;return n;}
 static Node parse(String s,boolean predicate){Formula p=new Formula(s);Node n=p.expression();if(p.at!=p.tokens.size())throw new IllegalArgumentException("Sobran partes de la formula");type(n,predicate);return n;}
 static String natural(String raw){String s=Knowledge.normalize(raw).trim();s=s.replaceAll("\\bsu doble\\b","(x*2)").replaceAll("\\bsu triple\\b","(x*3)").replaceAll("\\bsu cuadrado\\b","(x*x)");String[] words={"cero","uno","dos","tres","cuatro","cinco","seis","siete","ocho","nueve","diez"};for(int i=0;i<words.length;i++)s=s.replaceAll("\\b"+words[i]+"\\b",""+i);s=s.replaceAll("\\b(?:cada numero|cada elemento|el numero|el elemento)\\b","x").replaceAll("\\bes mayor o igual que\\b",">=").replaceAll("\\bes menor o igual que\\b","<=").replaceAll("\\bes mayor que\\b",">").replaceAll("\\bes menor que\\b","<").replaceAll("\\bes igual a\\b","==").replaceAll("\\bes distinto de\\b","!=").replaceAll("\\bmultiplicado por\\b","*").replaceAll("\\bdividido por\\b","/").replaceAll("\\bmas\\b","+").replaceAll("\\bmenos\\b","-").replaceAll("\\bpor\\b","*");java.util.regex.Matcher m=java.util.regex.Pattern.compile("^si (.+) entonces (.+) sino (.+)$").matcher(s);if(m.matches())s="("+m.group(1)+")?("+m.group(2)+"):("+m.group(3)+")";return s;}
}
